import{_ as t,o as s,c as o,ah as e}from"./chunks/framework.Yx0DUrwu.js";const _=JSON.parse('{"title":"scvi-tools 教程","description":"","frontmatter":{},"headers":[],"relativePath":"tools/scvi-tools/index.md","filePath":"tools/scvi-tools/index.md","lastUpdated":1787830595000}'),r={name:"tools/scvi-tools/index.md"};function n(l,a,i,c,p,d){return s(),o("div",null,[...a[0]||(a[0]=[e('<h1 id="scvi-tools-教程" tabindex="-1">scvi-tools 教程 <a class="header-anchor" href="#scvi-tools-教程" aria-label="Permalink to &quot;scvi-tools 教程&quot;">​</a></h1><p>scvi-tools 是 scverse 生态中的深度生成模型工具箱，常用于批次整合、低维潜空间学习、差异表达、参考映射和多组学模型。它不是 Scanpy 的替代品，而是常接在 AnnData/Scanpy 预处理之后，用模型化方式处理批次和噪声。</p><p>官方快速入门和教程的核心思路是：准备 AnnData，保留原始计数，把批次/协变量元数据放进 obs，用 <code>setup_anndata()</code> 告诉模型数据在哪里，然后训练 <code>SCVI</code> 或其它模型。</p><div class="path-grid"><a href="/tools/scvi-tools/integration-latent-space"><strong>整合与潜空间</strong><span>学习 setup_anndata、SCVI 模型训练、潜在表示、邻居图、UMAP 和聚类。</span></a><a href="/tools/anndata/"><strong>AnnData 基础</strong><span>理解 scvi-tools 为什么依赖 layers、obs 和原始计数。</span></a><a href="/tools/scanpy/"><strong>Scanpy 对接</strong><span>用 Scanpy 做 QC 和可视化，用 scvi-tools 学经过批次校正的潜空间。</span></a><a href="/references/"><strong>参考资料</strong><span>查看 scvi-tools 官方文档、模型论文和实践教程。</span></a></div><h2 id="什么时候使用" tabindex="-1">什么时候使用 <a class="header-anchor" href="#什么时候使用" aria-label="Permalink to &quot;什么时候使用&quot;">​</a></h2><div class="check-grid"><article><strong>多样本整合</strong><span>多个供体、批次、建库化学体系或条件混在一起时，用潜变量模型学习共享空间。</span></article><article><strong>参考映射</strong><span>把新数据映射到已有参考图谱，减少每次从头注释的成本。</span></article><article><strong>概率差异表达</strong><span>用模型不确定性辅助差异表达判断，但仍需结合实验设计。</span></article><article><strong>多组学模型</strong><span>TOTALVI、MULTIVI 等模型可用于 RNA + 蛋白或 RNA + ATAC 数据。</span></article></div><h2 id="资料来源" tabindex="-1">资料来源 <a class="header-anchor" href="#资料来源" aria-label="Permalink to &quot;资料来源&quot;">​</a></h2><ul><li><a href="https://docs.scvi-tools.org/" target="_blank" rel="noreferrer">scvi-tools documentation</a></li><li><a href="https://docs.scvi-tools.org/en/stable/tutorials/notebooks/quick_start/api_overview.html" target="_blank" rel="noreferrer">scvi-tools quick start</a></li><li><a href="https://www.sc-best-practices.org/" target="_blank" rel="noreferrer">Single Cell Best Practices</a></li></ul>',8)])])}const g=t(r,[["render",n]]);export{_ as __pageData,g as default};
